458	```javascript
459	// Function words that would otherwise crowd every ranking. The list is
460	// deliberately short and fixed: callers who need a different list can filter
461	// the full ranking (pass a large n) themselves.
462	const STOP_WORDS = new Set([
463	  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'for', 'from', 'had', 'has',
464	  'have', 'he', 'her', 'his', 'i', 'in', 'is', 'it', 'its', 'of', 'on', 'or',
465	  'she', 'that', 'the', 'their', 'there', 'they', 'this', 'to', 'was', 'were',
466	  'will', 'with',
467	]);
468	
469	/**
470	 * List the most frequent words in a piece of text.
471	 *
472	 * Words are lower-cased, typographic apostrophes are folded to straight ones,
473	 * and stop words are skipped. Entries are ordered by count (highest first),
474	 * then alphabetically, so the result is deterministic.
475	 *
476	 * @param {string} text
477	 * @param {number} n How many entries to return; a non-negative integer.
478	 * @returns {Array<{word: string, count: number}>}
479	 */
480	function topWords(text, n) {
481	  assertText('topWords', text);
482	  if (!Number.isInteger(n) || n < 0) {
483	    throw new RangeError(`topWords: n must be a non-negative integer, received ${String(n)}`);
484	  }
485	  const counts = new Map();
486	  for (const token of tokenize(text)) {
487	    const word = token.toLowerCase().replace(/’/g, "'");
488	    if (STOP_WORDS.has(word)) {
489	      continue;
490	    }
491	    counts.set(word, (counts.get(word) ?? 0) + 1);
492	  }
493	  return [...counts]
494	    .map(([word, count]) => ({ word, count }))
495	    .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
496	    .slice(0, n);
497	}
498	
499	module.exports = { wordCount, sentenceCount, topWords };
500	```
